def set_app_icon(window: tk.Misc, *, default: bool = False):
    """Apply the icon; cache photos per Tcl interpreter, never across Tk roots."""
    root = window._root()
    images = root.__dict__.get("_ifc_app_icon_images")
    if images is None:
        images = tuple(tk.PhotoImage(master=root, data=data) for data in _ICON_PNGS)
        root._ifc_app_icon_images = images
    window.iconphoto(default, *images)
